package com.itb.inf2dm.absencemanager.services;
import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.*;import com.itb.inf2dm.absencemanager.model.entity.Turma;import com.itb.inf2dm.absencemanager.model.repository.TurmaRepository;@Service public class TurmaService{ @Autowired private TurmaRepository repo; public List<Turma> findAll(){return repo.findAll();} public Turma findById(Long id){return repo.findById(id).orElseThrow();} public Turma create(Turma t){return repo.save(t);} public Turma update(Long id,Turma t){Turma x=findById(id); x.setNome(t.getNome()); return repo.save(x);} public void delete(Long id){repo.deleteById(id);} }